import{z as n,x as o,o as B,c as p,q as t,j as s,D as A,d as a,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"证书与 PKI","description":"","frontmatter":{"title":"证书与 PKI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cert-pki.md","filePath":"cs/cert-pki.md","lastUpdated":1791063341000}'),C={name:"cs/cert-pki.md"};function d(D,E,F,c,m,h){const r=o("Mermaid");return B(),p("div",null,[E[2]||(E[2]=t('<h1 id="证书与-pki" tabindex="-1">证书与 PKI <a class="header-anchor" href="#证书与-pki" aria-label="Permalink to &quot;证书与 PKI&quot;">​</a></h1><div class="epigraph"><p>证书把公钥绑到名字，并用另一把私钥签名；信任是对签发者的，不是对那串比特本身的神秘属性。</p><footer>—— 据 RFC 5280（X.509）；Anderson 对 PKI 失败模式的整理</footer></div><p><a href="/cs/mac-signature">上一课</a>给出可公开验证的签名。本课不重写验签算法。缺口是：对方递来的公钥为什么是「银行」而不是中间人。<a href="/cs/mac-signature">TLS 入口</a>已经假定证书存在；这里把 PKI 收成：根锚、链、撤销，以及信任锚本身是配置不是协议推出来的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信封和签名都要 \\(pk\\)。若 \\(pk\\) 来自刚连上的对端，威胁模型里的主动者可以换钥匙。缺口不是新的公钥算法，而是<strong>绑定</strong>：证书 = 名字 + 公钥 + 元数据，由 CA 的私钥签名。<span class="marginnote">证书可以类比成公证处盖章的介绍信：写明「持钥者叫这个名字、钥匙长这个样（公钥）、有效期到哪天」，公证处（CA）用它的私钥盖章。你不认识持钥人没关系，只要信任公证处不会乱盖章——信任的落点从「千百个对端」缩到「少数几个 CA」。</span>验证者预置根证书，沿链验到叶子。名字还要与用户意图（主机名）一致，否则链再真也绑错对象。</p><p><span class="marginnote">浏览器根程序决定锚。CA 被骗或被强制签发，链仍然密码学合法——PKI 的完整性依赖 CA 与撤销，不单依赖签名方案。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>X.509 链：叶子由中间签，中间由根签。验证：路径、有效期、密钥用法、主机名（SAN）。撤销：CRL 或 OCSP，失败策略决定可用性与安全的挤法。本课不把 CT 日志的全部生态写完，只承认：仅验链不够应对误签，透明日志是补丁。</p>',8)),(B(),s(l,null,{default:A(()=>[i(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E9%A2%84%E7%BD%AE%E6%A0%B9%E9%94%9A%22%5D%20--%3E%20CHAIN%5B%22%E9%AA%8C%E8%AF%81%E4%B9%A6%E9%93%BE%22%5D%0A%20%20CHAIN%20--%3E%20NAME%5B%22%E5%90%8D%E5%AD%97%E5%8C%B9%E9%85%8D%22%5D%0A%20%20NAME%20--%3E%20SESS%5B%22%E5%90%8E%E8%AF%BE%E4%BC%9A%E8%AF%9D%20%2F%20%E5%8F%A3%E4%BB%A4%22%5D%0A%20%20CHAIN%20--%3E%20PWD%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%8F%A3%E4%BB%A4%E4%B8%8E%E5%8A%A0%E7%9B%90%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("PKI 把「谁的公钥」从每次人工比对指纹，变成对少数锚的信任。这服务 TLS 握手里的服务器认证；客户端证书较少见，机制相同。与"),e("a",{href:"/cs/two-pc"},"两阶段提交"),a("对照：2PC 假设参与者身份已定；PKI 要在开放网络上建立身份。锚泄露或算法过时，要轮换根——那是运维，不是握手能单独修的。")],-1)),E[5]||(E[5]=e("p",null,"主机名检查发生在链验证之后：链真而名字错，仍是中间人几何。",-1)),(B(),s(l,null,{default:A(()=>[i(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAF%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%80%92%E6%9D%A5%E5%8F%B6%E5%AD%90%E8%AF%81%E4%B9%A6%22%5D%20--%3E%20V1%7B%22%E6%AF%8F%E4%B8%AA%E7%AD%BE%E5%90%8D%E8%83%BD%E9%AA%8C%E5%88%B0%E9%A2%84%E7%BD%AE%E6%A0%B9%E9%94%9A%EF%BC%9F%22%7D%0A%20%20V1%20--%3E%7C%22%E5%90%A6%22%7C%20F1%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E9%93%BE%E6%96%AD%EF%BC%8C%E5%85%AC%E9%92%A5%E6%97%A0%E5%87%BA%E5%A4%84%22%5D%0A%20%20V1%20--%3E%7C%22%E6%98%AF%22%7C%20V2%7B%22%E6%95%B4%E6%9D%A1%E9%93%BE%E9%83%BD%E5%9C%A8%E6%9C%89%E6%95%88%E6%9C%9F%E5%86%85%EF%BC%9F%22%7D%0A%20%20V2%20--%3E%7C%22%E5%90%A6%22%7C%20F2%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E8%BF%87%E6%9C%9F%E6%88%96%E6%9C%AA%E7%94%9F%E6%95%88%22%5D%0A%20%20V2%20--%3E%7C%22%E6%98%AF%22%7C%20V3%7B%22%E5%AF%86%E9%92%A5%E7%94%A8%E6%B3%95%E4%B8%8E%E4%B8%BB%E6%9C%BA%E5%90%8D%E5%8C%B9%E9%85%8D%EF%BC%9F%22%7D%0A%20%20V3%20--%3E%7C%22%E5%90%A6%22%7C%20F3%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E9%93%BE%E7%9C%9F%E4%BD%86%E7%BB%91%E9%94%99%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20V3%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E4%BF%A1%E4%BB%BB%E5%BB%BA%E7%AB%8B%EF%BC%8C%E6%8F%A1%E6%89%8B%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">这张图回答「验证一个证书到底查几道、各挡什么攻击」：第一道挡「假钥匙」（没出处），第二道挡「旧钥匙」，第三道挡「真钥匙绑错名」。初学者最容易省略第三道——攻击者拿一张自己域名的合法证书，链完全真，就能顶替银行；名字对不上必须拒。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 DANE/DNSSEC 与 Web PKI 混成一课。也不把「自签证书」当成 PKI 失败：它只是把锚放到对端自己，适合已有带外信任。<span class="marginnote">自签证书类比「自己给自己写介绍信」：对外没人认，但在你已经认识对方的小圈子里（公司内网、自己的设备），把信任锚直接设成对方本人反而省去公证处一环——这是合法用法，不是体系故障。判断标准是「锚怎么进到验证者手里」有没有带外保证。</span>本课不讲区块链替代 CA。</p><p>叶子密钥轮换要发新证书；锚轮换要更新每个验证者的预置，周期长得多。后课默认：开放网上的公钥来自证书链与名字检查；人的口令是另一条身份路径，要单独存储与盐。</p><p>时间错误会让有效证书被拒、过期证书被收。可用与完整在时钟上相遇，本课只要求验证包含有效期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>链上的每一个签名都要验；跳过中间用途检查等于换锚。</p></li><li><p>后课口令是人的秘密路径，与机器证书并列，不互相替代。</p></li><li><p>签名可验；本课把公钥绑到名字，信任落在根锚与 CA。</p></li><li><p>链合法 ≠ 名字对、≠ CA 没被骗。</p></li><li><p>人记得的秘密如何存，是口令课缺口。</p></li><li><p>出处：RFC 5280；Anderson, <em>Security Engineering</em>；对照 RFC 8446 对证书的使用。</p></li></ul>',7))])}const f=n(C,[["render",d]]);export{P as __pageData,f as default};
